//! The raw stream of a request a capture is watching: every SSE event as received, before the
//! parse that splits it into reasoning, content and tool calls (card fb6d7912).
//!
//! A captured response records what the adapter PARSED (`TextGenerationResponse`), which
//! cannot say whether a wrong tool call was generated by the model or produced by the parse.
//! On 2026-10-12 a citizen's first call of several turns executed as `work/create` titled "x"
//! while her reasoning in the SAME response planned another call, and no record anywhere held
//! the tokens that would settle it (Astra and Kimi swept the trace, the captures and the logs).
//!
//! Normalization, named exactly: an event is the bytes between two blank lines, with every
//! `\r` removed (the stream reader drops them before it splits events) and decoded as UTF-8
//! lossily. Nothing else is touched: `data:` prefixes, other SSE fields, keepalives and
//! `[DONE]` are kept.
//!
//! Each streaming ATTEMPT is kept separately, in order, because the parser starts fresh on
//! every attempt: concatenating an interrupted attempt with its retry would replay arguments
//! that never existed (Astra on #4978). The last attempt is the one the response came from.
//!
//! Only the capture owner arms a tap, and only for a call it is recording, so a request no
//! capture watches costs one map lookup at stream start and nothing per event.

use std::collections::HashMap;
use std::sync::LazyLock;

use parking_lot::Mutex;
use serde::Serialize;

/// What a capture saw of one request's raw stream.
#[derive(Debug, Default, Clone, PartialEq, Eq, Serialize)]
pub struct Wire {
    /// One entry per streaming attempt, each its events in arrival order. The last attempt is
    /// the one the recorded response came from.
    pub attempts: Vec<Vec<String>>,
    /// An attempt was still streaming when the call ended; its events are not in `attempts`.
    /// Said, never implied by a shorter stream.
    pub open_at_end: bool,
}

#[derive(Default)]
struct Watch {
    attempts: Vec<Vec<String>>,
    /// Attempts streaming now.
    open: usize,
    /// The call ended while `open > 0`: late attempts are discarded, and the entry goes when
    /// the last one closes.
    closed: bool,
}

static TAPS: LazyLock<Mutex<HashMap<String, Watch>>> = LazyLock::new(Default::default);

/// Watch `request_id`'s stream: the capture owner calls this before dispatch.
pub fn arm(request_id: &str) {
    TAPS.lock().entry(request_id.to_owned()).or_default();
}

/// What `request_id` streamed, ending the watch. `None` when it was never armed. The capture
/// owner calls this when it records the call's end, on every path, so no watch outlives its
/// call: an attempt still open is reported as `open_at_end` and cleans up when it closes.
pub fn take(request_id: &str) -> Option<Wire> {
    let mut taps = TAPS.lock();
    let watch = taps.get_mut(request_id)?;
    let wire = Wire {
        attempts: std::mem::take(&mut watch.attempts),
        open_at_end: watch.open > 0,
    };
    if watch.open > 0 {
        watch.closed = true;
    } else {
        taps.remove(request_id);
    }
    Some(wire)
}

/// One streaming attempt's side: collects events locally (no lock per event) and deposits
/// them as one attempt when it ends, including on an error return, so a failed attempt is
/// recorded too.
pub(crate) struct WireTap {
    request_id: Option<String>,
    events: Vec<String>,
}

impl WireTap {
    pub(crate) fn open(request_id: Option<&str>) -> Self {
        let request_id = request_id.and_then(|id| {
            let mut taps = TAPS.lock();
            let watch = taps.get_mut(id).filter(|watch| !watch.closed)?;
            watch.open += 1;
            Some(id.to_owned())
        });
        Self {
            request_id,
            events: Vec::new(),
        }
    }

    pub(crate) fn push(&mut self, event: &str) {
        if self.request_id.is_some() {
            self.events.push(event.to_owned());
        }
    }
}

impl Drop for WireTap {
    fn drop(&mut self) {
        let Some(id) = self.request_id.take() else {
            return;
        };
        let mut taps = TAPS.lock();
        let Some(watch) = taps.get_mut(&id) else {
            return;
        };
        watch.open = watch.open.saturating_sub(1);
        if watch.closed {
            if watch.open == 0 {
                taps.remove(&id);
            }
            return;
        }
        watch.attempts.push(std::mem::take(&mut self.events));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // what this catches: a captured call whose raw stream is lost, merged across attempts, or
    // whose watch outlives the call. An armed request keeps each attempt separately and in
    // order; an unarmed one keeps nothing; a tap still open when the call ends is reported
    // (open_at_end), never deposited into a closed watch, and its entry is removed when it
    // closes.
    #[test]
    fn an_armed_request_keeps_each_attempt_and_says_when_one_was_still_open() {
        let id = format!("wire-test-{}", uuid::Uuid::new_v4());
        let mut unwatched = WireTap::open(Some(&id));
        unwatched.push("data: {}");
        drop(unwatched);
        assert_eq!(take(&id), None, "nothing is kept for a request no capture armed");

        arm(&id);
        let mut interrupted = WireTap::open(Some(&id));
        interrupted.push("data: {\"partial\":1}");
        drop(interrupted);
        let mut retry = WireTap::open(Some(&id));
        retry.push("data: {\"whole\":1}");
        retry.push("data: [DONE]");
        drop(retry);
        let wire = take(&id).expect("the armed stream was kept");
        assert_eq!(wire.attempts.len(), 2, "one entry per attempt, never merged");
        assert_eq!(wire.attempts[1], vec!["data: {\"whole\":1}", "data: [DONE]"]);
        assert!(!wire.open_at_end);
        assert_eq!(take(&id), None, "taken once");

        // The call ends while an attempt is still streaming (a cancelled turn).
        let id = format!("wire-test-{}", uuid::Uuid::new_v4());
        arm(&id);
        let mut streaming = WireTap::open(Some(&id));
        streaming.push("data: {\"mid\":1}");
        let wire = take(&id).expect("armed");
        assert!(wire.open_at_end && wire.attempts.is_empty(), "the open attempt is said, not hidden");
        assert!(WireTap::open(Some(&id)).request_id.is_none(), "a closed watch takes no new attempt");
        drop(streaming);
        assert!(!TAPS.lock().contains_key(&id), "the entry goes when its last attempt closes");
        assert_eq!(WireTap::open(None).request_id, None);
    }
}
